  ballast: number | null;
  // ballast plus norm; null (n/a) when ballast or norm is.
  keystone: number | null;
  // keel minus norm; null (n/a) when keel or norm is.
  bearing: number | null;
  // keel plus momentum; null (n/a) when keel is.
  pitch: number | null;

